CREATE TABLE ot_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL DEFAULT 'attendee', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ot_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(150) NOT NULL, description TEXT NOT NULL, venue VARCHAR(200) NOT NULL, category VARCHAR(30) NOT NULL, starts_at DATETIME NOT NULL, capacity INT UNSIGNED NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'draft', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX event_status_date(status,starts_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ot_bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, event_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, code CHAR(32) NOT NULL UNIQUE, name VARCHAR(100) NOT NULL, email VARCHAR(254) NOT NULL, quantity INT UNSIGNED NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'confirmed', checked_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(event_id) REFERENCES ot_events(id), FOREIGN KEY(user_id) REFERENCES ot_users(id), INDEX event_inventory(event_id,status), INDEX user_bookings(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ot_settings (name VARCHAR(60) PRIMARY KEY, value TEXT NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE ot_throttle (bucket CHAR(64) PRIMARY KEY,hits INT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
